steps.analogousExample:
/* Example: styling a positioned element */
button {
  position: relative;
  background-color: #007bff;
  color: white;
  padding: 10px 20px;
  border: none;
  border-radius: 4px;
}

/* Positioning a tooltip relative to a button */
.tooltip {
  position: absolute;
  top: 100%;
  left: 0;
}

/* Example of using anchor() for positioning */
.popup {
  position: absolute;
  top: anchor(--my-anchor bottom);
  left: anchor(--my-anchor right);
}

/* Similar: linking an element to an anchor */
.tooltip {
  position-anchor: --trigger-button;
}

/* Positioning relative to anchor edges */
.element {
  top: anchor(top);
  left: anchor(right);
}

